//#region src/core/parse-input.ts
/** 结尾的分隔符，输入已归一化为 `/` */
const RE_ENDING_SLASH = /\/+$/;
/** 任意路径分隔符，`\\` 用于兼容 Windows 路径 */
const RE_SLASH = /[/\\]+/g;
/**
* 去掉结尾的分隔符
*
* @param value 已归一化的路径
* @returns 去掉结尾分隔符的路径
*/
function removeEndingSlashes(value) {
	return value.replace(RE_ENDING_SLASH, "");
}
/**
* 解析输入路径，得到用于匹配的名称与文件夹判定
*
* 处理顺序：`\` 与连续分隔符统一为 `/` → 记录是否以分隔符结尾
* → 去掉结尾分隔符 → 取最后一段作为匹配名称并转为小写。
*
* @param input 输入路径或文件名，非字符串输入按空路径处理
* @returns 小写的匹配名称，以及是否能确定是文件夹
*/
function parseFilePath(input) {
	const normalized = (typeof input === "string" ? input.replace(RE_SLASH, "/") : "").trim();
	const isFolder = normalized.endsWith("/");
	const trimmed = removeEndingSlashes(normalized);
	const index = trimmed.lastIndexOf("/");
	return {
		name: (index === -1 ? trimmed : trimmed.slice(index + 1)).toLowerCase(),
		isFolder
	};
}
//#endregion
//#region src/core/transformer.ts
/**
* 将声明式图标集合展平为运行时查找表
*
* 1. 把 `图标名 → 名称[]` 反转为 `名称 → 图标名` 的无原型对象，避免原型链属性被误命中；
* 2. 精确匹配的规则（`exact !== false` 且 `extensions !== '*'`）在此预展开为具名文件，
*    运行时只需一次哈希查找；只有 `exact: false` / `'*'` 规则保留在 `fileStems` 中按声明顺序匹配。
*
* 五个查找表在 `IconSet` 中均为可选，缺省时按空表处理。
*
* @param iconSet 图标集合
* @returns 展平后的查找表
*/
function transformer(iconSet) {
	const folderNames = transformNamedIconSet(iconSet.folderNames);
	const fileNames = transformNamedIconSet(iconSet.fileNames);
	const fileExtensions = transformNamedIconSet(iconSet.fileExtensions);
	const languageIds = transformNamedIconSet(iconSet.languageIds, normalizeLanguageId);
	const fileStems = [];
	for (const [icon, stems] of Object.entries(iconSet.fileStems ?? {})) for (const { name, extensions, exact } of stems) if (exact === false || extensions === "*") fileStems.push({
		name,
		icon,
		extensions
	});
	else for (const extension of extensions) {
		const ext = extension ? `.${extension}` : "";
		fileNames[name + ext] = icon;
	}
	return {
		folderNames,
		fileNames,
		fileExtensions,
		languageIds,
		fileStems
	};
}
/**
* 归一化 language id
*
* language id 大小写不敏感：查找前输入会去除首尾空白并转为小写，
* 因此建表时使用同一套规则归一化键，使数据中的 `Cangjie`、`Swagger` 这类写法同样能被命中。
*
* @param value language id
* @returns 归一化后的 language id
*/
function normalizeLanguageId(value) {
	return value.trim().toLowerCase();
}
/**
* 将 `图标名 → 名称[]` 反转为 `名称 → 图标名` 的无原型对象
*
* 同一名称被多个图标声明时，后声明者覆盖先声明者。
*
* @param data 图标名与名称列表的映射
* @param normalizeKey 键的归一化函数，缺省时原样建表
* @returns 名称与图标名的映射
*/
function transformNamedIconSet(data = {}, normalizeKey) {
	const result = Object.create(null);
	for (const [icon, names] of Object.entries(data)) for (const name of names) result[normalizeKey ? normalizeKey(name) : name] = icon;
	return result;
}
//#endregion
//#region src/core/create-finder.ts
/**
* 检查查找表是否包含指定键
*
* 查找表为无原型对象，且建表时已去重，
* 这里同时校验键值不为 `undefined`，兼容 JS 消费方传入的异常数据。
*
* @param obj - 查找表
* @param key - 目标键名
* @returns 是否命中（键存在且值为字符串）
*/
function hasOwn(obj, key) {
	return Object.prototype.hasOwnProperty.call(obj, key) && obj[key] !== void 0;
}
/**
* 收集图标集合中缺失的必填字段
*
* 只有 `collect` 与 `defaults` 是必填项：二者是图标名前缀与兜底图标，
* 缺失时会产生 `undefined:file` 这类非法图标名。五个查找表均可选，缺省时按空表处理。
*
* @param iconSet - 图标集合（可能不完整）
* @returns 缺失字段名列表，必填字段齐全时为空数组
*/
function collectMissingFields(iconSet) {
	const missing = [];
	if (!iconSet.collect) missing.push("collect");
	if (!iconSet.defaults?.file) missing.push("defaults.file");
	if (!iconSet.defaults?.folder) missing.push("defaults.folder");
	return missing;
}
/**
* 构造三类默认图标
*
* @param collect - 图标集合前缀
* @param defaults - 图标集合默认图标名
* @param folderExpandedSuffix - 文件夹图标展开态后缀
* @returns 文件 / 文件夹 / 语言三类默认图标
*/
function createDefaultIcons(collect, defaults, folderExpandedSuffix) {
	const configuredFolderExpanded = defaults.folderExpanded ?? "";
	const defaultFolderExpanded = configuredFolderExpanded.length > 0 ? configuredFolderExpanded : defaults.folder + folderExpandedSuffix;
	return {
		file: {
			type: "file",
			name: `${collect}:${defaults.file}`
		},
		folder: {
			type: "folder",
			name: `${collect}:${defaults.folder}`,
			expandedName: `${collect}:${defaultFolderExpanded}`
		},
		language: {
			type: "language",
			name: `${collect}:${defaults.file}`
		}
	};
}
/**
* 创建单一图标集下的文件图标查找器
*
* 构造时通过 `transformer` 将声明式图标集合展平为查找表，
* 之后的每次查找都是纯同步的查表，无 I/O、无异步。
*
* @param iconSet - 图标集合
* @returns 图标查找器
* @throws {TypeError} 缺少必填字段（`collect`、`defaults.file`、`defaults.folder`）时抛出，避免后续查找产生难以定位的错误；
* 这里只校验必填字段，查找表与规则的形状由类型约束，不做运行时校验
*/
function createFinder(iconSet) {
	const missingFields = collectMissingFields(iconSet);
	if (missingFields.length > 0) {
		const fields = missingFields.join(", ");
		throw new TypeError(`[find-file-icon] Invalid IconSet: missing ${fields}`);
	}
	const { fileNames, fileExtensions, fileStems, folderNames, languageIds } = transformer(iconSet);
	const { collect, defaults, folderExpandedSuffix = "", filePrefix = "", folderPrefix = "" } = iconSet;
	const { file, folder, language } = createDefaultIcons(collect, defaults, folderExpandedSuffix);
	/**
	* 查找文件夹图标
	*
	* 仅支持精确匹配，命中即返回折叠态与展开态两个图标名。
	*
	* @param foldername - 文件夹名
	* @returns 文件夹图标信息，未命中时为 `undefined`
	*/
	const findFolder = (foldername) => {
		if (!hasOwn(folderNames, foldername)) return;
		const icon = `${collect}:${folderPrefix}${folderNames[foldername]}`;
		return {
			type: "folder",
			name: icon,
			expandedName: icon + folderExpandedSuffix
		};
	};
	/**
	* 标准化文件图标
	*
	* 文件图标名由集合前缀、文件前缀与图标名拼接而成。
	*
	* @param name - 图标名
	* @returns 文件图标信息
	*/
	const normalizeFile = (name) => ({
		type: "file",
		name: `${collect}:${filePrefix}${name}`
	});
	/**
	* 查找文件图标
	*
	* 查找优先级：具名文件精确匹配 → 文件名规则（按声明顺序）→ 扩展名（最长后缀优先）。
	*
	* @param filename - 文件名
	* @returns 文件图标信息，未命中时为 `undefined`
	*/
	const findFile = (filename) => {
		if (hasOwn(fileNames, filename)) return normalizeFile(fileNames[filename]);
		for (const { name, icon, extensions } of fileStems) {
			if (!filename.startsWith(name)) continue;
			if (extensions === "*" && (filename === name || filename[name.length] === ".")) return normalizeFile(icon);
			if (extensions !== "*" && extensions.length && filename[name.length] === "." && extensions.some((ext) => filename.endsWith(`.${ext}`))) return normalizeFile(icon);
		}
		let index = filename.indexOf(".");
		while (index !== -1) {
			const extension = filename.slice(index + 1);
			if (hasOwn(fileExtensions, extension)) return normalizeFile(fileExtensions[extension]);
			index = filename.indexOf(".", index + 1);
		}
	};
	/**
	* 查找语言图标
	*
	* 语言图标与文件图标同属一个图标族，图标名同样由集合前缀与文件前缀拼接而成。
	* language id 大小写不敏感，这里与建表时使用同一套归一化规则。
	*
	* @param input - 原始 language id，可含首尾空白
	* @returns 语言图标信息，未命中时为 `undefined`
	*/
	const findLanguage = (input) => {
		const languageId = normalizeLanguageId(input);
		if (!hasOwn(languageIds, languageId)) return;
		return {
			type: "language",
			name: `${collect}:${filePrefix}${languageIds[languageId]}`
		};
	};
	const iconFinder = (input, type) => {
		if (type === "language") return findLanguage(typeof input === "string" ? input : "") ?? { ...language };
		const { name, isFolder } = parseFilePath(input);
		if (type === "folder") return findFolder(name) ?? { ...folder };
		if (type === "file") return findFile(name) ?? { ...file };
		if (isFolder) return findFolder(name) ?? { ...folder };
		return findFile(name) ?? findFolder(name) ?? findLanguage(name) ?? { ...file };
	};
	return iconFinder;
}
//#endregion
export { createFinder as t };
